from bisect import bisect_right


def build_regions(request):
    """Build a compact region graph from a public floor request.

    The floor is subdivided by every coordinate that can change the blocked
    status of a cell or the fee of a boundary side.  Each compressed interval
    is therefore a homogeneous rectangle: all of its cells are either blocked
    or free, and the fee for crossing one of its four sides is constant across
    that side.  Free rectangles are the nodes; sides with total fee zero are
    unioned into regions, while positive-fee sides become region graph edges.
    """

    width, height = request["size"]
    entry = request["entry"]

    xs = {0, width}
    ys = {0, height}

    # Normalise blocked rectangles to their intersection with the floor.
    blocked_rects = []
    for rect in request.get("blocked", []):
        x0, y0, x1, y1 = rect
        if x0 > x1:
            x0, x1 = x1, x0
        if y0 > y1:
            y0, y1 = y1, y0
        x0 = max(0, x0)
        x1 = min(width, x1)
        y0 = max(0, y0)
        y1 = min(height, y1)
        if x1 <= x0 or y1 <= y0:
            continue
        blocked_rects.append((x0, y0, x1, y1))
        xs.add(x0)
        xs.add(x1)
        ys.add(y0)
        ys.add(y1)

    # Normalise walls.  Only the portion inside the floor matters, and a wall
    # lying exactly on the floor boundary cannot be crossed anyway.
    parsed_walls = []
    for wall in request.get("walls", []):
        seg = wall["segment"]
        fee = wall.get("fee")
        x0, y0, x1, y1 = seg
        if x0 == x1:
            if y0 > y1:
                y0, y1 = y1, y0
            if x0 <= 0 or x0 >= width:
                continue
            y0 = max(0, y0)
            y1 = min(height, y1)
            if y1 <= y0:
                continue
            parsed_walls.append(("v", x0, y0, y1, fee))
            xs.add(x0)
            ys.add(y0)
            ys.add(y1)
        elif y0 == y1:
            if x0 > x1:
                x0, x1 = x1, x0
            if y0 <= 0 or y0 >= height:
                continue
            x0 = max(0, x0)
            x1 = min(width, x1)
            if x1 <= x0:
                continue
            parsed_walls.append(("h", y0, x0, x1, fee))
            ys.add(y0)
            xs.add(x0)
            xs.add(x1)

    xs = sorted(xs)
    ys = sorted(ys)
    x_index = {value: i for i, value in enumerate(xs)}
    y_index = {value: i for i, value in enumerate(ys)}
    nx = len(xs) - 1
    ny = len(ys) - 1

    # Sweep blocked rectangles over y-intervals to get covered x-intervals.
    starts = [[] for _ in range(ny + 1)]
    ends = [[] for _ in range(ny + 1)]
    for x0, y0, x1, y1 in blocked_rects:
        ix0 = x_index[x0]
        ix1 = x_index[x1]
        iy0 = y_index[y0]
        iy1 = y_index[y1]
        starts[iy0].append((ix0, ix1))
        ends[iy1].append((ix0, ix1))

    # Build one graph node per free compressed rectangle.
    node_id = {}
    node_area = []
    active = []
    for j in range(ny):
        for span in ends[j]:
            active.remove(span)
        for span in starts[j]:
            active.append(span)

        spans = []
        if active:
            active.sort()
            cur_x0, cur_x1 = active[0]
            for x0, x1 in active[1:]:
                if x0 <= cur_x1:
                    if x1 > cur_x1:
                        cur_x1 = x1
                else:
                    spans.append((cur_x0, cur_x1))
                    cur_x0, cur_x1 = x0, x1
            spans.append((cur_x0, cur_x1))

        span_index = 0
        for i in range(nx):
            while span_index < len(spans) and spans[span_index][1] <= i:
                span_index += 1
            if span_index < len(spans) and spans[span_index][0] <= i < spans[span_index][1]:
                continue
            node_id[(i, j)] = len(node_area)
            node_area.append((xs[i + 1] - xs[i]) * (ys[j + 1] - ys[j]))

    # Precompute fees for compressed boundary sides.  A missing key means no
    # wall covers that side, so the crossing is free.
    vertical_fees = {}
    horizontal_fees = {}

    def add_fee(mapping, key, fee):
        record = mapping.get(key)
        if record is None:
            record = [0, False]
            mapping[key] = record
        if fee is None:
            record[1] = True
        else:
            record[0] += fee

    for kind, a, b, c, fee in parsed_walls:
        if kind == "v":
            boundary_i = x_index[a] - 1
            j_start = y_index[b]
            j_end = y_index[c]
            for j in range(j_start, j_end):
                add_fee(vertical_fees, (boundary_i, j), fee)
        else:
            boundary_j = y_index[a] - 1
            i_start = x_index[b]
            i_end = x_index[c]
            for i in range(i_start, i_end):
                add_fee(horizontal_fees, (i, boundary_j), fee)

    # Union zero-fee neighbours and collect positive-fee region edges.
    parent = list(range(len(node_area)))
    rank = [0] * len(node_area)

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1

    positive_edges = []

    def consider_neighbour(a, b, mapping, key):
        record = mapping.get(key)
        if record is None:
            union(a, b)
            return
        if record[1]:
            return
        fee = record[0]
        if fee == 0:
            union(a, b)
        else:
            positive_edges.append((a, b, fee))

    for (i, j), a in node_id.items():
        b = node_id.get((i + 1, j))
        if b is not None:
            consider_neighbour(a, b, vertical_fees, (i, j))
        b = node_id.get((i, j + 1))
        if b is not None:
            consider_neighbour(a, b, horizontal_fees, (i, j))

    # Assign region ids and total areas.
    root_to_region = {}
    region_of_node = [-1] * len(node_area)
    areas = []
    for node in range(len(node_area)):
        root = find(node)
        region = root_to_region.get(root)
        if region is None:
            region = len(areas)
            root_to_region[root] = region
            areas.append(0)
        region_of_node[node] = region
        areas[region] += node_area[node]

    neighbours = [{} for _ in areas]
    for a, b, fee in positive_edges:
        ra = region_of_node[a]
        rb = region_of_node[b]
        if ra == rb:
            continue
        old = neighbours[ra].get(rb)
        if old is None or fee < old:
            neighbours[ra][rb] = fee
        old = neighbours[rb].get(ra)
        if old is None or fee < old:
            neighbours[rb][ra] = fee

    entry_i = bisect_right(xs, entry[0]) - 1
    entry_j = bisect_right(ys, entry[1]) - 1
    entry_node = node_id.get((entry_i, entry_j))
    if entry_node is None:
        raise ValueError("entry cell is outside the free floor")

    return {
        "areas": areas,
        "neighbors": [sorted(value.items()) for value in neighbours],
        "start": region_of_node[entry_node],
    }

import heapq


def fee_areas(regions):
    """Return the public area-by-fee report for a region graph."""
    areas = regions["areas"]
    neighbours = regions["neighbors"]
    start = regions["start"]

    distances = [None] * len(areas)
    distances[start] = 0
    queue = [(0, start)]
    while queue:
        distance, node = heapq.heappop(queue)
        if distance != distances[node]:
            continue
        for neighbour, fee in neighbours[node]:
            candidate = distance + fee
            old = distances[neighbour]
            if old is None or candidate < old:
                distances[neighbour] = candidate
                heapq.heappush(queue, (candidate, neighbour))

    area_by_fee = {}
    unreachable = 0
    for node, distance in enumerate(distances):
        if distance is None:
            unreachable += areas[node]
            continue
        key = str(distance)
        area_by_fee[key] = area_by_fee.get(key, 0) + areas[node]

    return {"area_by_fee": area_by_fee, "unreachable": unreachable}

