class TransformBehaviourTests(unittest.TestCase):
    def test_public_fixture_report(self):
        request = {
            "size": [8, 5],
            "entry": [0, 0],
            "blocked": [],
            "walls": [
                {"segment": [3, 0, 3, 3], "fee": 9},
                {"segment": [3, 3, 3, 5], "fee": 1},
                {"segment": [0, 3, 3, 3], "fee": 1},
                {"segment": [3, 3, 8, 3], "fee": 1},
            ],
        }
        result = call_candidate(
            "engines/analysis/engine.py",
            "transform",
            args=[{"request": request}, {"task": "F15", "name": "analysis"}],
        )
        self.assertEqual(
            result,
            {
                "area_by_fee": {"0": 9, "1": 6, "2": 10, "3": 15},
                "unreachable": 0,
            },
        )

    def test_overlapping_fees_and_null_wall_partition(self):
        # Two walls on one shared side add their fees; a null-fee wall closes
        # the second side and makes the last region unreachable.
        request = {
            "size": [3, 1],
            "entry": [0, 0],
            "blocked": [],
            "walls": [
                {"segment": [1, 0, 1, 1], "fee": 2},
                {"segment": [1, 0, 1, 1], "fee": 3},
                {"segment": [2, 0, 2, 1], "fee": None},
            ],
        }
        result = call_candidate(
            "engines/analysis/engine.py",
            "transform",
            args=[{"request": request}, {"task": "F15", "name": "analysis"}],
        )
        self.assertEqual(
            result,
            {"area_by_fee": {"0": 1, "5": 1}, "unreachable": 1},
        )

    def test_large_coordinate_extent_without_cell_enumeration(self):
        # A huge floor with a single wall must still produce exact areas.
        height = width = 10**9
        request = {
            "size": [width, height],
            "entry": [0, 0],
            "blocked": [],
            "walls": [{"segment": [1, 0, 1, height], "fee": 1}],
        }
        result = call_candidate(
            "engines/analysis/engine.py",
            "transform",
            args=[{"request": request}, {"task": "F15", "name": "analysis"}],
        )
        self.assertEqual(
            result,
            {
                "area_by_fee": {"0": height, "1": (width - 1) * height},
                "unreachable": 0,
            },
        )

    def test_blocked_half_open_rectangle_excluded(self):
        # [0,0,2,2] covers cells x=0,1 and y=0,1, leaving five free cells.
        request = {
            "size": [3, 3],
            "entry": [2, 0],
            "blocked": [[0, 0, 2, 2]],
            "walls": [],
        }
        result = call_candidate(
            "engines/analysis/engine.py",
            "transform",
            args=[{"request": request}, {"task": "F15", "name": "analysis"}],
        )
        self.assertEqual(result, {"area_by_fee": {"0": 5}, "unreachable": 0})


